import {FURNITURE} from './furniture-catalogue.js';
import {HOME_BOUNDS,HOME_FIXED_COLLIDERS,HOME_SOFA_COLLIDER,HOME_ACCESS,HOME_ACTIVITY_SPACE} from './home-layout.js';
export function migrateDecor(s,data){s.decor=validDecor(data?.decor)?structuredClone(data.decor):{version:1,serial:0,items:[],receipts:[]};const moved=[];for(const i of s.decor.items)if(i.placed&&!validatePlacement(s,i).ok){i.placed=false;moved.push(i.id);}s.homeLayoutVersion=2;s.layoutMoved=data?.homeLayoutVersion===2?[]:moved;}
export function validDecor(d){return !!d&&d.version===1&&Number.isSafeInteger(d.serial)&&d.serial>=0&&d.serial<=1000000000&&Array.isArray(d.items)&&d.items.length<=40&&new Set(d.items.map(i=>i?.id)).size===d.items.length&&d.items.every(i=>i&&/^furn-[0-9]{1,10}$/.test(i.id)&&Number(i.id.slice(5))<=d.serial&&FURNITURE[i.item]&&typeof i.placed==='boolean'&&Number.isFinite(i.x)&&Math.abs(i.x)<=6.6&&Number.isFinite(i.z)&&i.z>=-6.1&&i.z<=4.1&&[0,1,2,3].includes(i.turn))&&Array.isArray(d.receipts)&&d.receipts.length<=64&&new Set(d.receipts.map(r=>r?.order)).size===d.receipts.length&&d.receipts.every(r=>r&&typeof r.order==='string'&&r.order.length<=80&&d.items.some(i=>i.id===r.id));}
export function furnitureFootprint(instance){const item=FURNITURE[instance.item];return {x:instance.x,z:instance.z,w:instance.turn%2?item.d:item.w,d:instance.turn%2?item.w:item.d};}
const overlap=(a,b,pad=0)=>Math.abs(a.x-b.x)<(a.w+b.w)/2+pad&&Math.abs(a.z-b.z)<(a.d+b.d)/2+pad;
export function decorColliders(s,except){return s.decor.items.filter(i=>i.placed&&i.id!==except&&!FURNITURE[i.item].flat).map(furnitureFootprint);}
export function validatePlacement(s,instance){
 const item=FURNITURE[instance.item];if(!item||![0,1,2,3].includes(instance.turn)||!Number.isFinite(instance.x+instance.z))return {ok:false,message:'Choose a valid item and position.'};
 const box=furnitureFootprint(instance);if(box.x-box.w/2< -6.55||box.x+box.w/2>6.55||box.z-box.d/2< -6.05||box.z+box.d/2>4.05)return {ok:false,message:'Keep the whole item inside the room.'};
 const base=[...HOME_FIXED_COLLIDERS,...(s.furniture?[HOME_SOFA_COLLIDER]:[])],other=decorColliders(s,instance.id);
 if(!item.flat&&[...base,...other].some(b=>overlap(box,b,.06)))return {ok:false,message:'This overlaps furniture or a wall.'};
 if((item.flat?HOME_ACTIVITY_SPACE.slice(0,1):HOME_ACTIVITY_SPACE).some(b=>overlap(box,b,.06)))return {ok:false,message:'Leave the doorway and activity space clear.'};
 if(item.flat){if(s.decor.items.some(i=>i.placed&&i.id!==instance.id&&FURNITURE[i.item].flat&&overlap(box,furnitureFootprint(i),.03)))return {ok:false,message:'This overlaps another rug.'};return {ok:true,message:'Ready to place.'};}
 const obstacles=[...base,...other,box],step=.2,minX=-6.4,minZ=-5.8,nx=65,nz=49,open=(x,z)=>!obstacles.some(b=>Math.abs(x-b.x)<b.w/2+.29&&Math.abs(z-b.z)<b.d/2+.29),seen=new Set(),queue=[];
 const cell=p=>[Math.round((p.x-minX)/step),Math.round((p.z-minZ)/step)],start=cell(HOME_ACCESS[0]);queue.push(start);seen.add(start[1]*nx+start[0]);
 for(let at=0;at<queue.length;at++){const [x,z]=queue[at];for(const [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){const a=x+dx,b=z+dz,key=b*nx+a;if(a<0||a>=nx||b<0||b>=nz||seen.has(key)||!open(minX+a*step,minZ+b*step))continue;seen.add(key);queue.push([a,b]);}}
 for(const point of HOME_ACCESS){const [x,z]=cell(point);let reached=false;for(let dz=-1;dz<=1;dz++)for(let dx=-1;dx<=1;dx++)if(seen.has((z+dz)*nx+x+dx)&&Math.hypot(minX+(x+dx)*step-point.x,minZ+(z+dz)*step-point.z)<.31)reached=true;if(!reached)return {ok:false,message:'This would block a route to the door or an activity.'};}
 return {ok:true,message:'Ready to place. Doors and activities remain reachable.'};
}
export function buyFurniture(s,itemId,order){const item=FURNITURE[itemId];if(!item||typeof order!=='string'||!order||order.length>80)return {ok:false,message:'Choose an item.'};const receipt=s.decor.receipts.find(r=>r.order===order);if(receipt)return {ok:true,id:receipt.id,charged:0,message:'Already purchased. Find it in your collection.'};if(s.decor.items.length>=40)return {ok:false,message:'Your collection holds up to 40 pieces.'};if(s.money<item.price)return {ok:false,message:'You need ₦'+(item.price-s.money).toLocaleString()+' more.'};const id='furn-'+(++s.decor.serial);s.money-=item.price;s.stats.purchases++;s.decor.items.push({id,item:itemId,placed:false,x:0,z:0,turn:0});s.decor.receipts.push({order,id});s.decor.receipts=s.decor.receipts.slice(-64);return {ok:true,id,charged:item.price,message:item.name+' is in storage. Choose its position.'};}
export function placeFurniture(s,id,position){const item=s.decor.items.find(i=>i.id===id);if(!item)return {ok:false,message:'That piece is not owned.'};const draft={...item,...position,id:item.id,item:item.item,placed:true},result=validatePlacement(s,draft);if(result.ok)Object.assign(item,{x:draft.x,z:draft.z,turn:draft.turn,placed:true});return result;}
export function storeFurniture(s,id){const item=s.decor.items.find(i=>i.id===id);if(!item)return false;item.placed=false;return true;}
